import {normalizeLivery} from './vehicle-livery.js';
import {isMedicalBay} from './station-layout.js';
export const STATION_KEY='valmont.station.v1';
const localFleet=fleet=>fleet?.length&&fleet.every(e=>e.localVolunteer);
const storageKey=fleet=>localFleet(fleet)?'valmont.station.south.v1':STATION_KEY;
export const CATALOG={PC:{label:'PC · poste de commandement',group:'fire',crew:2},VPCE:{label:'VPCE · berce alimentation',group:'fire',crew:2},PS:{label:'PS · premier secours évacuation',group:'medical',crew:6},VSAV:{label:'VSAV · cellule',group:'medical',crew:3},VLI:{label:'VLI',group:'medical',crew:1},VSR:{label:'VSR · secours routier',group:'fire',crew:3},FPT:{label:'FPT · 3 000 L',group:'fire',crew:6},FPTSR:{label:'FPTSR · 3 000 L',group:'fire',crew:6},FPTL:{label:'FPTL · 2 000 L',group:'fire',crew:4},CCFL:{label:'CCFL · 2 000 L',group:'fire',crew:4},CCF:{label:'CCFM · 4 000 L',group:'fire',crew:4},CCF8000:{label:'CCFS · 8 000 L',group:'fire',crew:4},EPA:{label:'EPA',group:'fire',crew:2},VTU:{label:'VTU',group:'fire',crew:2},VPL:{label:'VPL + bateau',group:'fire',crew:3}};
export const ccfLabel=e=>e.lightForest?'CCFL':(e.tankCapacity||e.capacity||4000)>=8000?'CCFS':'CCFM';
export const modelKey=e=>e.firstAid?'PS':e.kind==='CCF'&&e.lightForest?'CCFL':e.kind==='FPT'?(e.lightPump?'FPTL':e.roadRescueEquipment===false?'FPT':'FPTSR'):e.kind==='CCF'&&e.tankCapacity===8000?'CCF8000':e.kind;
export function defaultComposition(fleet){return fleet.filter(e=>e.kind!=='VLCG').map(e=>({type:modelKey(e),livery:'service',...(e.kind==='FPT'?{signalRear:'round-single'}:{}),signal:e.kind==='CCF'?'round':'standard',foam:true,lighting:true}));}
export function signalChoices(type){if(['CCFL','CCF','CCF8000'].includes(type))return ['round'];return ['PS','VSAV','VSAV_MAN','VSAV_MASTER'].includes(type)?['standard','short','wide','round','round-single','round-double']:['FPT','FPTSR','FPTL','VSR'].includes(type)?['standard','wide','round','round-single','round-double']:['CCF','CCF8000','EPA'].includes(type)?['standard','round']:['standard'];}
export function signalZoneChoices(type,zone){if(zone==='Rear'&&['FPT','FPTSR','FPTL'].includes(type))return ['round-single','round-double','none'];return ['CCFL','CCF','CCF8000'].includes(type)?['round','round-single','round-double','none']:['standard','short','wide','round','round-single','round-double','none'];}
export const AMBER_CHOICES=['standard','none','short','wide','round','round-single','round-double'];
export function normalizeComposition(raw,fleet){const defaults=defaultComposition(fleet),slots=fleet.filter(e=>e.kind!=='VLCG');return defaults.map((fallback,i)=>{let row=Array.isArray(raw)?raw[i]:null;if(['VSAV_MASTER','VSAV_MAN'].includes(row?.type))row={...row,type:'VSAV'};if(!row||typeof row!=='object')return fallback;const medical=isMedicalBay(slots[i]),type=row.type===''?'':CATALOG[row.type]?.group===(medical?'medical':'fire')?row.type:fallback.type;const allowed=signalZoneChoices(type),signalFront=allowed.includes(row.signalFront)?row.signalFront:allowed.includes(row.signal)?row.signal:allowed[0],signalRear=signalZoneChoices(type,'Rear').includes(row.signalRear)?row.signalRear:signalZoneChoices(type,'Rear').includes(row.signal)?row.signal:signalZoneChoices(type,'Rear')[0];return {type,livery:normalizeLivery(row.livery),signalFront,signalRear,signalAmber:AMBER_CHOICES.includes(row.signalAmber)?row.signalAmber:'standard',signal:signalChoices(type).includes(row.signal)?row.signal:signalChoices(type)[0],foam:row.foam!==false,lighting:row.lighting!==false};});}
export function compositionErrors(rows,fleet){if(localFleet(fleet))return rows.some(r=>r.type==='VLI'||(CATALOG[r.type]?.crew||0)>4)?['Le CIS Sud utilise des équipages SPV de quatre personnes au maximum, sans VLI dédié.']:[];const types=rows.map(r=>r.type);const missing=['VSAV','FPTSR','EPA','VPL'].filter(t=>t==='VSAV'?!types.some(k=>['PS','VSAV','VSAV_MAN','VSAV_MASTER'].includes(k)):t==='FPTSR'?!(types.includes('FPTSR')||types.includes('FPT')&&types.includes('VSR')):!types.includes(t));if(!types.some(t=>['CCFL','CCF','CCF8000'].includes(t)))missing.push('CCF');return [...(missing.length?['Pour couvrir les missions du jeu, conserver : '+missing.map(t=>t==='FPTSR'?'FPTSR ou FPT + VSR':t).join(', ')+'.']:[]),...(types.filter(t=>t==='VLI').length>1?['Un seul VLI : un infirmier est disponible.']:[])];}
export function loadComposition(fleet,storage=globalThis.localStorage){try{const raw=JSON.parse(storage?.getItem(storageKey(fleet))||'null');if(!raw)return null;const rows=normalizeComposition(raw,fleet);return compositionErrors(rows,fleet).length?null:rows;}catch{return null;}}
export function saveComposition(rows,fleet,storage=globalThis.localStorage){const clean=normalizeComposition(rows,fleet),errors=compositionErrors(clean,fleet);if(errors.length)return {error:errors.join(' ')};try{if(!storage)throw Error();storage.setItem(storageKey(fleet),JSON.stringify(clean));return {rows:clean};}catch{return {error:'Enregistrement impossible dans ce navigateur.'};}}
export function composedFleet(fleet,rows,templateFleet=fleet){if(!rows)return fleet;const templates=new Map(templateFleet.map(e=>[modelKey(e),e])),slots=fleet.filter(e=>e.kind!=='VLCG'),counts={};const result=[];for(const [i,row]of normalizeComposition(rows,fleet).entries()){if(!row.type)continue;const base=row.type==='PS'?{...templates.get('VSAV'),kind:'VSAV',firstAid:true,tankCapacity:880,size:6,name:'Premier secours évacuation · 880 L · cellule sanitaire'}:row.type==='FPT'?{...templates.get('FPTSR'),kind:'FPT',lightPump:false,roadRescueEquipment:false,tankCapacity:3000,size:6,name:'Fourgon pompe-tonne'}:['PC','VPCE'].includes(row.type)?{...templates.get('FPTSR'),kind:row.type,tankCapacity:0,size:2,name:row.type==='PC'?'Poste de commandement':'Porteur · berce alimentation longue distance'}:row.type==='CCFL'?{...templates.get('CCF'),lightForest:true,longChassis:false,tankCapacity:2000,size:4,name:'CCFL · citerne 2 000 L'}:row.type==='VSR'?{...templates.get('FPTSR'),kind:'VSR',tankCapacity:0,size:3,name:'Véhicule de secours routier'}:templates.get(row.type);if(!base)continue;const prefix=['VSAV_MAN','VSAV_MASTER'].includes(row.type)?'VSAV':['CCFL','CCF','CCF8000'].includes(row.type)?ccfLabel(base):row.type,n=counts[prefix]=(counts[prefix]||0)+1;const id=['FPTSR','VSR','EPA','VTU'].includes(prefix)&&n===1?prefix:prefix+' '+n;result.push({...base,...(localFleet(fleet)?{external:true,mutualAid:true,localVolunteer:true,localIndex:slots[i].localIndex,base:'CIS Sud',baseYaw:Math.PI,mobilization:12}:{}),id:localFleet(fleet)?prefix+' Sud'+(n>1?' '+n:''):id,home:[...slots[i].home],livery:row.livery,signalStyle:row.signal,signalFront:row.signalFront,signalRear:row.signalRear,signalAmber:row.signalAmber,foamEnabled:row.foam,lightingEnabled:row.lighting});}return [...result,...fleet.filter(e=>e.kind==='VLCG')];}
